import java.util.Scanner;

public class JavaApplication1 {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String firstLine = scan.nextLine();
        String secondLine = scan.nextLine();
        String replaced = secondLine.replaceAll("_+", " ").trim();
        StringBuilder insideText = new StringBuilder();
        int insideFlag = 0;
        for (char ch : replaced.toCharArray()) {
            if (ch == '(') {
                insideFlag = 1;
            } else if (ch == ')') {
                insideText.append(' ');
                insideFlag = 0;
            } else if (insideFlag == 1) {
                insideText.append(ch);
            }
        }
        String s = secondLine;
        int position;
        while ((position = s.indexOf('(')) != -1) {
            int endPos = s.indexOf(')', position);
            if (endPos == -1) break;
            s = s.substring(0, position) + " " + s.substring(endPos + 1);
        }
        s = s.replaceAll(" +", " ").trim();
        String insideStr = insideText.toString().replaceAll(" +", " ").trim();
        String[] outArr = s.split(" ");
        String[] inArr = insideStr.split(" ");
        int maxLen = 0;
        for (String word : outArr) {
            if (word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        if (!insideStr.isEmpty()) {
            System.out.println(maxLen + " " + inArr.length);
        } else {
            System.out.println(maxLen + " 0");
        }
    }
}
